files.store/migrations/m0002_merge_customers.p:
"""Make customers.email unique, ignoring ASCII case.

Customers whose emails are equal after trimming surrounding spaces and ignoring ASCII case are one person. Keep the
one with the earliest created_at (the lowest id on a tie), move every order and address of the others to it, and
delete the others. If the kept customer's name is NULL or empty, give it the name of the earliest-created duplicate
that has one. Store every customer's email trimmed, with ASCII letters lowercased; other characters stay as they are.

Afterwards the customers table declares email as `email TEXT NOT NULL COLLATE NOCASE UNIQUE`. Everything else in the
schema stays as it is: the same tables and columns, the foreign keys with ON DELETE CASCADE, the index and the view.
Every order and address survives. conn comes from store.db.connect, with foreign keys on and no open transaction;
leave foreign keys on, commit your work, and set user_version to 2.
"""

NEW_CUSTOMERS = """CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL COLLATE NOCASE UNIQUE,
    name TEXT,
    created_at TEXT NOT NULL
)"""

_ASCII_LOWER = str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")


def _normalize(email):
    # Trim surrounding spaces only; lowercase ASCII letters only.
    return email.strip(" ").translate(_ASCII_LOWER)


def _has_name(name):
    return name is not None and name != ""


def upgrade(conn):
    # Foreign keys can only be toggled outside a transaction. Turn them off so the customers table can be rebuilt
    # without cascading deletes into orders/addresses, and always turn them back on.
    conn.execute("PRAGMA foreign_keys = OFF")
    try:
        conn.execute("BEGIN IMMEDIATE")
        try:
            _migrate(conn)
            problems = conn.execute("PRAGMA foreign_key_check").fetchall()
            if problems:
                raise RuntimeError(f"foreign key violations after migration: {problems!r}")
            conn.execute("PRAGMA user_version = 2")
            conn.commit()
        except BaseException:
            conn.rollback()
            raise
    finally:
        conn.execute("PRAGMA foreign_keys = ON")


def _migrate(conn):
    rows = conn.execute("SELECT id, email, name FROM customers ORDER BY created_at, id").fetchall()

    groups = {}
    for cid, email, name in rows:
        groups.setdefault(_normalize(email), []).append((cid, email, name))

    for key, members in groups.items():
        keep_id, keep_email, keep_name = members[0]
        others = members[1:]
        for other_id, _, _ in others:
            conn.execute("UPDATE orders SET customer_id = ? WHERE customer_id = ?", (keep_id, other_id))
            conn.execute("UPDATE addresses SET customer_id = ? WHERE customer_id = ?", (keep_id, other_id))
        if not _has_name(keep_name):
            for _, _, other_name in others:
                if _has_name(other_name):
                    conn.execute("UPDATE customers SET name = ? WHERE id = ?", (other_name, keep_id))
                    break
        for other_id, _, _ in others:
            conn.execute("DELETE FROM customers WHERE id = ?", (other_id,))
        if keep_email != key:
            conn.execute("UPDATE customers SET email = ? WHERE id = ?", (key, keep_id))

    # Rebuild customers with the new email declaration (https://sqlite.org/lang_altertable.html#otheralter).
    # Views and triggers that mention customers must be dropped first and recreated afterwards, otherwise the
    # schema is left referring to a missing table; indexes on customers are dropped with the table.
    dependents = conn.execute(
        "SELECT type, name, sql FROM sqlite_schema"
        " WHERE type IN ('view', 'trigger') AND sql IS NOT NULL ORDER BY rowid"
    ).fetchall()
    customer_indexes = conn.execute(
        "SELECT sql FROM sqlite_schema"
        " WHERE type = 'index' AND tbl_name = 'customers' AND sql IS NOT NULL ORDER BY rowid"
    ).fetchall()
    for kind, name, _ in reversed(dependents):
        conn.execute(f'DROP {kind.upper()} "{name.replace(chr(34), chr(34) * 2)}"')

    # Copy out, drop, and recreate under the original name (no RENAME, so the stored CREATE text stays clean).
    conn.execute("CREATE TEMP TABLE m0002_customers AS SELECT id, email, name, created_at FROM customers")
    conn.execute("DROP TABLE customers")
    conn.execute(NEW_CUSTOMERS)
    conn.execute(
        "INSERT INTO customers (id, email, name, created_at) SELECT id, email, name, created_at FROM m0002_customers"
    )
    conn.execute("DROP TABLE temp.m0002_customers")

    for (sql,) in customer_indexes:
        conn.execute(sql)
    for _, _, sql in dependents:
        conn.execute(sql)
